p { margin: 0 0 1rem; color: var(--text-soft); }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }

.container { width: min(1120px, 92%); margin: 0 auto; }
.section { padding: 5rem 0; }
.section-tight { padding: 3.5rem 0; }

header {
  position: sticky;
  top: 0;
  z-index: 30;
  backdrop-filter: blur(10px);
  background: rgba(13, 19, 33, .85);
  border-bottom: 1px solid rgba(255,255,255,.06);
}
.navbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: 74px;
}
.logo {
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  font-size: 1.35rem;
  display: flex;
  align-items: center;
  gap: .5rem;
}
.logo-dot {
  width: 12px;
  height: 12px;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  box-shadow: 0 0 18px rgba(255,138,30,.8);
}
.nav-links {
  display: flex;
  align-items: center;
  gap: 1.3rem;
}
.nav-links a { color: var(--text-soft); font-weight: 500; }
.nav-links a:hover, .nav-links a.active { color: var(--text); }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  border: 0;
  border-radius: 12px;
  font-weight: 600;
  padding: .78rem 1.15rem;
  cursor: pointer;
  min-height: 44px;
  transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary {
  background: linear-gradient(135deg, var(--accent), #ff6b00);
  color: #fff;
  box-shadow: 0 10px 24px rgba(255,138,30,.35);
}
.btn-secondary { background: var(--card-2); color: var(--text); border: 1px solid var(--line); }
.btn-ghost { background: transparent; color: var(--text); border: 1px solid var(--line); }

.hero {
  display: grid;
  gap: 2.2rem;
  grid-template-columns: 1.15fr .85fr;
  align-items: center;
}
.hero h1 { font-size: clamp(2rem, 4vw, 3.4rem); }
.lead { font-size: 1.08rem; max-width: 58ch; }
.hero-card {
  background: linear-gradient(160deg, #1a2640 10%, #111a2a 100%);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.2rem;
  box-shadow: var(--shadow);
}

.badges { display: flex; flex-wrap: wrap; gap: .7rem; margin: 1.2rem 0 1.5rem; }
.badge {
  padding: .45rem .7rem;
  border-radius: 999px;
  font-size: .86rem;
  background: rgba(45,212,191,.12);
  border: 1px solid rgba(45,212,191,.3);
  color: #b6fff4;
}

.grid-3 { display: grid; gap: 1rem; grid-template-columns: repeat(3, 1fr); }
.grid-2 { display: grid; gap: 1.2rem; grid-template-columns: repeat(2, 1fr); }
