  background: linear-gradient(180deg, var(--card) 0, #0f1727 100%);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1.2rem;
}

.stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 1rem;
}
.stat { text-align: center; background: var(--card); border: 1px solid var(--line); border-radius: 12px; padding: 1rem; }
.stat-number { font-size: clamp(1.6rem, 3vw, 2.2rem); font-weight: 700; color: var(--text); }
.stat-label { font-size: .92rem; color: var(--text-soft); }

.carousel { position: relative; overflow: hidden; }
.testimonial-track { display: flex; transition: transform .35s ease; }
.testimonial { min-width: 100%; }
.carousel-controls { display: flex; gap: .7rem; margin-top: 1rem; }
.icon-btn {
  width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--line);
  background: var(--card-2); color: var(--text); cursor: pointer;
}

.pricing-toggle {
  display: inline-flex;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: .25rem;
  gap: .2rem;
}
.pricing-toggle button {
  border: 0;
  background: transparent;
  color: var(--text-soft);
  padding: .5rem .9rem;
  border-radius: 999px;
  cursor: pointer;
  min-height: 40px;
}
.pricing-toggle button.active { background: #233252; color: var(--text); }
.price { font-size: 2rem; font-weight: 700; margin: .8rem 0; }
.price small { font-size: .95rem; color: var(--text-soft); font-weight: 500; }

.table-wrap { overflow-x: auto; }
table {
  width: 100%;
  border-collapse: collapse;
  min-width: 720px;
  background: var(--card);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
}
th, td { padding: .9rem .85rem; border-bottom: 1px solid var(--line); text-align: left; }
th { background: #18233a; }

.accordion-item { border: 1px solid var(--line); border-radius: 12px; margin-bottom: .8rem; overflow: hidden; background: var(--card); }
.accordion-btn {
  width: 100%; text-align: left; border: 0; background: transparent; color: var(--text);
  padding: 1rem; font-weight: 600; cursor: pointer;
}
.accordion-panel { max-height: 0; overflow: hidden; transition: max-height .25s ease; }
.accordion-panel p { padding: 0 1rem 1rem; margin: 0; }
.accordion-item.open .accordion-panel { max-height: 180px; }

form { display: grid; gap: .9rem; }
label { font-weight: 600; font-size: .92rem; }
input, textarea, select {
  width: 100%;
  background: #0d1628;
  border: 1px solid var(--line);
  color: var(--text);
  border-radius: 10px;
  padding: .72rem .8rem;
  min-height: 44px;
}
textarea { min-height: 120px; resize: vertical; }
.error { color: #fda4af; font-size: .85rem; min-height: 1.1rem; }
.success-message {
  display: none;
  margin-top: .7rem;
  padding: .75rem;
  border: 1px solid rgba(34,197,94,.4);
  background: rgba(34,197,94,.12);
  color: #b7ffcf;
  border-radius: 10px;
}

.cta {
  background: linear-gradient(130deg, #1f2c48, #151f33);
  border: 1px solid #304368;
  border-radius: 18px;
  padding: clamp(1.4rem, 3vw, 2.3rem);
}

.footer { border-top: 1px solid rgba(255,255,255,.08); padding: 2rem 0; color: var(--text-soft); font-size: .95rem; }

.menu-btn {
  display: none;
  width: 44px; height: 44px;
  border-radius: 10px;
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--text);
}
.mobile-drawer {
  position: fixed;
  top: 0;
  right: -100%;
  width: min(84vw, 340px);
  height: 100vh;
  background: #0f1728;
  border-left: 1px solid var(--line);
  padding: 1.2rem;
  z-index: 40;
  transition: right .28s ease;
}
.mobile-drawer.open { right: 0; }
.mobile-drawer nav { display: grid; gap: .75rem; margin-top: 1rem; }
.drawer-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,.45);
  z-index: 35;
  display: none;
}
.drawer-overlay.show { display: block; }

@media (max-width: 980px) {
